use imu_joint_bridge::protocol::Server;
use serde_json::json;
fn ready()->Server{let mut s=Server::default();s.native(json!({"kind":"native_clock_req","sid":"native-session","seq":0,"nonce":"n","n1_ns":1}),1792300000000000,1792300000000010).unwrap();s}
#[test]fn selected_duration_bound_to_hello(){for d in[20000,60000,120000]{let mut s=ready();let a=s.watch(json!({"p":"J_HELLO1","sid":"watch","w1_ms":1792300000000u64,"duration_ms":d}),1792300000000000,1792300000000010).unwrap();assert_eq!(a.reply["duration_ms"],d);}}
#[test]fn unknown_duration_does_not_take_watch_identity(){let mut s=ready();assert!(s.watch(json!({"p":"J_HELLO1","sid":"bad","w1_ms":1792300000000u64,"duration_ms":60001}),1792300000000000,1792300000000010).is_err());let a=s.watch(json!({"p":"J_HELLO1","sid":"good","w1_ms":1792300000000u64,"duration_ms":60000}),1792300000000000,1792300000000010).unwrap();assert_eq!(a.reply["sid"],"good");}
#[test]fn archive_identity_is_bounded_and_path_free(){use imu_joint_bridge::protocol::archive_request;assert!(archive_request(&json!({"kind":"export_session","sid":"native-session","nonce":"nonce"})).is_ok());for v in[json!({"kind":"export_session","sid":"../other","nonce":"nonce"}),json!({"kind":"export_session","sid":"session","nonce":true}),json!({"kind":"export_session","sid":"session","nonce":"nonce","path":"other"})]{assert!(archive_request(&v).is_err());}}
